import_if_exists "repos/${owner}/${repo}/labels/受領済み" "github_issue_label.juryou_zumi" "${repo}:受領済み"
import_if_exists "repos/${owner}/${repo}/labels/改善" "github_issue_label.kaizen" "${repo}:改善"
import_if_exists "repos/${owner}/${repo}/labels/隔離" "github_issue_label.kakuri" "${repo}:隔離"
import_if_exists "repos/${owner}/${repo}/labels/公開停止" "github_issue_label.koukai_teishi" "${repo}:公開停止"
import_if_exists "repos/${owner}/${repo}/labels/l5-condition" "github_issue_label.l5_condition" "${repo}:l5-condition"
